// === Tab: mySketch ===
let t = 0;
let angleY = 0;
let rows = 80;
let cols = 200;
let radius = 300;

function setup() {
  createCanvas(800, 800, WEBGL);
  frameRate(60);
  smooth(0); // pixel sharp
  noCursor();
}

function draw() {
  background(0);
  translate(width / 2, height / 2);
  rotateX(HALF_PI);
  rotateZ(radians(-15));
  rotateY(angleY);

  stroke(255);
  strokeWeight(0.6);

  let freq = 12.0;
  let speed = 0.015;

  for (i = 0; i < rows; i++) {
    let phi = map(i, 0, rows - 1, -HALF_PI, HALF_PI);
    let y = radius * sin(phi);
    let r = radius * cos(phi);

    for (j = 0; j < cols; j++) {
      let theta = map(j, 0, cols, 0, TWO_PI);
      let x = r * cos(theta);
      let z = r * sin(theta);

      // quantizzazione binaria: solo alcune linee vengono disegnate
      let phase = sin(theta * freq + t * 2.0 + i * 0.05);
      if (phase > 0.2) {
        line(x - 0.8, y, z, x + 0.8, y, z);
      }
    }
  }

  angleY += 0.002;
  t += 0.01;
}

